import logging
from typing import Optional, Callable

from pymilvus import MilvusClient
from pymilvus.client.types import DataType

from dataiku.core.vector_stores.dku_vector_store import DkuRemoteVectorStore, DistanceMetric
from dataiku.core.vector_stores.milvus_base_vector_store import MilvusBaseVectorStore, MilvusBaseDocumentFilter
from dataiku.core.vector_stores.vector_store_document_filter import ColumnType
from dataiku.langchain.dataset_loader import DummyLoader
from dataiku.langchain.metadata_generator import DKU_SECURITY_TOKENS_META, DKU_MULTIMODAL_CONTENT, DKU_DOCUMENT_INFO
from dataiku.llm.types import RetrievableKnowledge, BaseVectorStoreQuerySettings
from dataikuapi.dss.admin import DSSConnectionInfo

logging.getLogger("milvus").setLevel(logging.WARNING)

class MilvusRemoteVectorStore(MilvusBaseVectorStore, DkuRemoteVectorStore):

    def __init__(self, kb: RetrievableKnowledge, exec_folder: str, connection_info_retriever: Callable[[str], DSSConnectionInfo]):
        self.milvus_connection_info: Optional[DSSConnectionInfo] = None
        self.client = None
        self._conn_args = {}
        super(MilvusRemoteVectorStore, self).__init__(kb, exec_folder, connection_info_retriever)
        self.document_filter = MilvusRemoteDocumentFilter(self.metadata_column_type_and_meaning, self.original_to_sanitized_column_name)
        self.collection_name = self.index_name

    def init_connection(self) -> None:
        self.milvus_connection_info = self.connection_info_retriever(self.connection_name)

        params = self.milvus_connection_info.get_params()
        self._conn_args["uri"] = params["url"]
        if params["authType"] == "APIKEY":
            token = params["apiKey"]
        elif params["authType"] == "USER_PASS":
            token = params["user"] + ":" + params["password"]
        else:
            token = ""
        self._conn_args["token"] = token
        self.client = MilvusClient(**self._conn_args)

    def _db_exists(self):
        return self.client.has_collection(self.collection_name)

    def get_distance_metric(self):
        if self.distance_metric == DistanceMetric.DOT_PRODUCT:
            return "IP"
        elif self.distance_metric == DistanceMetric.EUCLIDEAN:
            return "L2"
        else:
            return "COSINE"

    def _build_metadata_schema(self):
        # All metadata fields should be `nullable` by default
        metadata_schema = {
            DKU_SECURITY_TOKENS_META: {
                "dtype": DataType.ARRAY,
                "kwargs": {"element_type": DataType.VARCHAR, "max_length": 255, "max_capacity": 4096, "nullable": True}
            }
        }
        for name, (column_type, meaning) in self.metadata_column_type_and_meaning.items():
            if meaning == "BagOfWordsMeaning":
                metadata_schema[name] = {
                    "dtype": DataType.ARRAY,
                    "kwargs": {"element_type": DataType.VARCHAR, "max_length": 255, "max_capacity": 4096, "nullable": True}
                }
            else:
                milvus_type = self.convert_dku_type_to_milvus_type(column_type)
                schema_kwargs = {"nullable": True}
                if milvus_type == DataType.VARCHAR:
                    schema_kwargs["max_length"] = 65535
                metadata_schema[name] = {
                    "dtype": milvus_type,
                    "kwargs": schema_kwargs
                }
        if self.kb.get("multimodalColumn"):
            string_kwargs = {"max_length": 65535, "nullable": True}
            metadata_schema[DKU_MULTIMODAL_CONTENT] = {"dtype": DataType.VARCHAR, "kwargs": string_kwargs}
            metadata_schema[DKU_DOCUMENT_INFO] = {"dtype": DataType.VARCHAR, "kwargs": string_kwargs}

        return metadata_schema

    @staticmethod
    def convert_dku_type_to_milvus_type(dku_type: str) -> DataType:
        if dku_type == "float":
            return DataType.FLOAT
        if dku_type == "double":
            return DataType.DOUBLE
        if dku_type == "tinyint":
            return DataType.INT8
        if dku_type == "smallint":
            return DataType.INT16
        if dku_type == "int":
            return DataType.INT32
        if dku_type == "bigint":
            return DataType.INT64
        if dku_type == "boolean":
            return DataType.BOOL
        else:
            return DataType.VARCHAR

    def clear_index(self) -> None:
        self.client.drop_collection(self.collection_name)

    def get_dummy_data_loader(self) -> DummyLoader:
        dummy_metadata = {}
        for k, v in self.milvus_metadata_schema.items():
            if v["dtype"] == DataType.ARRAY:
                dummy_metadata[k] = '[]'
            elif v["dtype"] == DataType.VARCHAR:
                dummy_metadata[k] = ""
            elif v["dtype"] == DataType.BOOL:
                dummy_metadata[k] = False
            else:
                dummy_metadata[k] = 0

        dummy_entry = {
            "page_content": "This is just a dummy query to check embeddingSize",
            "metadata": dummy_metadata
        }
        return DummyLoader([dummy_entry])


class MilvusRemoteDocumentFilter(MilvusBaseDocumentFilter):
    def _convert_item(self, item, column_type):
        if column_type == ColumnType.Integer:
            return int(item)
        elif column_type == ColumnType.Decimal:
            return float(item)
        else:
            return item
